"""Hornets: no AI. A 10-point genome over smell, hearing and ambush, steady-state evolution on sting reward.

Genes to behaviour:
    smell s    detects bees within Manhattan distance 2 + s
    hearing h  hears bee sounds within 2 * h cells (Euclidean) and follows one with probability h / 10
    ambush a   with probability a / 10 heads for a spot where it stung before or the bloom, and waits there
Hornets path on the true map (they are part of the environment) and never enter hive cells.
"""
from __future__ import annotations

import math
from collections import deque
from dataclasses import dataclass, field

from .world import DIRS4, World

GENES = ("smell", "hearing", "ambush")
POINTS = 10


def random_genome(rng) -> list[int]:
    g = [0, 0, 0]
    for _ in range(POINTS):
        g[rng.randrange(3)] += 1
    return g


def mutate(genes: list[int], rng, p: float = 0.5) -> list[int]:
    """With probability p, one point moves from one gene to another."""
    g = list(genes)
    if rng.random() < p:
        src = rng.choice([i for i in range(3) if g[i] > 0])
        dst = rng.choice([i for i in range(3) if i != src])
        g[src] -= 1
        g[dst] += 1
    return g


@dataclass
class Hornet:
    id: int
    x: int
    y: int
    genes: list[int]
    parent: int | None = None
    removed: float = 0.0
    ticks: int = 0
    target: int = -1
    mode: str = "wander"
    goal: tuple[int, int] | None = None
    goal_ttl: int = 0
    heading: tuple[int, int] = (1, 0)
    spots: list = field(default_factory=list)

    @property
    def fitness(self) -> float:
        return self.removed / max(1, self.ticks)

    @property
    def smell_range(self) -> int:
        return 2 + self.genes[0]

    @property
    def hearing_range(self) -> int:
        return 2 * self.genes[1]


def step_toward(world: World, start: tuple[int, int], goal: tuple[int, int], max_depth: int):
    """First step of a shortest hornet path from start to goal (or to a cell next to it), or None."""
    if start == goal:
        return None
    prev = {start: None}
    q = deque([(start, 0)])
    while q:
        c, d = q.popleft()
        if c == goal or (abs(c[0] - goal[0]) + abs(c[1] - goal[1]) == 1 and not world.open_for_hornet(*goal)):
            while prev[c] != start and prev[c] is not None:
                c = prev[c]
            return c if c != start else None
        if d >= max_depth:
            continue
        for dx, dy in DIRS4:
            n = (c[0] + dx, c[1] + dy)
            if n not in prev and world.open_for_hornet(*n):
                prev[n] = c
                q.append((n, d + 1))
    return None


class Swarm:
    def __init__(self, world: World, rng, *, frozen: bool = False, mutation: float = 0.5,
                 counts=(4, 6, 8, 0), evolve_every: int = 25, spawn_distance: int = 25, cooldown: int = 10):
        self.world, self.rng, self.frozen, self.mutation = world, rng, frozen, mutation
        self.counts, self.evolve_every, self.cooldown_ticks = counts, evolve_every, cooldown
        self.pool = [random_genome(rng) for _ in range(max(counts))]  # the initial draw; frozen hornets keep it
        dist = world.distances(world.home)
        self.spawn_cells = sorted(c for c, d in dist.items() if d >= spawn_distance and world.open_for_hornet(*c))
        self.active: list[Hornet] = []
        self.autumn: list[Hornet] = []
        self.next_id = 0
        self.cooldown: dict[tuple[int, int], int] = {}

    def _spawn(self, genes, parent=None) -> Hornet:
        x, y = self.spawn_cells[self.rng.randrange(len(self.spawn_cells))]
        h = Hornet(self.next_id, x, y, list(genes), parent, heading=DIRS4[self.rng.randrange(4)])
        self.next_id += 1
        self.active.append(h)
        return h

    def _pick_parent(self, pool: list[Hornet]) -> Hornet:
        total = sum(h.fitness for h in pool)
        if total <= 0:
            return pool[self.rng.randrange(len(pool))]
        r, acc = self.rng.random() * total, 0.0
        for h in pool:
            acc += h.fitness
            if acc >= r:
                return h
        return pool[-1]

    def season_start(self, season: int, year: int) -> list[Hornet]:
        """Bring hornets up to this season's count. Returns the new hornets. Winter makes them dormant."""
        if season == 3:
            self.autumn, self.active = list(self.active), []
            return []
        want, born = self.counts[season], []
        if season == 0 and year > 0:
            self.active = []
            parents = sorted(self.autumn, key=lambda h: (-h.fitness, h.id))[:want]
            for i in range(want):
                if self.frozen or not parents:
                    born.append(self._spawn(self.pool[i]))
                else:
                    p = parents[i % len(parents)]
                    born.append(self._spawn(mutate(p.genes, self.rng, self.mutation), p.id))
            return born
        while len(self.active) < want:
            i = len(self.active)
            if self.frozen or not self.active:
                born.append(self._spawn(self.pool[i]))
            else:
                p = self._pick_parent(self.active)
                born.append(self._spawn(mutate(p.genes, self.rng, self.mutation), p.id))
        return born

    def evolve(self) -> dict | None:
        """Replace the least fit hornet with a mutated copy of one chosen in proportion to fitness."""
        if self.frozen or len(self.active) < 2:
            return None
        worst = min(self.active, key=lambda h: (h.fitness, -h.ticks, h.id))
        self.active.remove(worst)
        parent = self._pick_parent(self.active)
        child = self._spawn(mutate(parent.genes, self.rng, self.mutation), parent.id)
        return {"removed": worst.id, "removed_fitness": round(worst.fitness, 4), "parent": parent.id,
                "child": child.id, "genes": child.genes, "x": child.x, "y": child.y}

    def move(self, bees: list[tuple[int, int, int, float]], sounds: list[tuple[int, int]], bloom: list[tuple[int, int]]) -> None:
        """One step for every hornet. bees: (id, x, y, life) for bees outside the hive; sounds: last tick's."""
        rng, world = self.rng, self.world
        for h in self.active:
            h.ticks += 1
            near = [b for b in bees if abs(b[1] - h.x) + abs(b[2] - h.y) <= h.smell_range]
            if near:
                tgt = next((b for b in near if b[0] == h.target), None)
                if tgt is None:
                    r, acc = rng.random() * sum(max(b[3], 1e-9) for b in near), 0.0
                    for tgt in near:
                        acc += max(tgt[3], 1e-9)
                        if acc >= r:
                            break
                h.target, h.mode, h.goal = tgt[0], "chase", None
                nxt = step_toward(world, (h.x, h.y), (tgt[1], tgt[2]), 3 * h.smell_range + 4)
                if nxt or abs(tgt[1] - h.x) + abs(tgt[2] - h.y) <= 1:
                    if nxt and abs(tgt[1] - h.x) + abs(tgt[2] - h.y) > 1:
                        h.x, h.y = nxt
                    continue
            h.target = -1
            heard = [s for s in sounds if math.dist(s, (h.x, h.y)) <= h.hearing_range]
            if heard and rng.random() < h.genes[1] / 10:
                h.goal = min(heard, key=lambda s: (math.dist(s, (h.x, h.y)), s))
                h.goal_ttl, h.mode = 2 * h.hearing_range, "sound"
            elif h.goal is None and rng.random() < h.genes[2] / 10:
                spots = h.spots + ([bloom[rng.randrange(len(bloom))]] if bloom else [])
                if spots:
                    h.goal, h.goal_ttl, h.mode = spots[rng.randrange(len(spots))], 80, "ambush"
            if h.goal is not None:
                h.goal_ttl -= 1
                if (h.x, h.y) == h.goal and h.mode == "ambush" and rng.random() < h.genes[2] / 10:
                    continue  # wait in ambush
                nxt = step_toward(world, (h.x, h.y), h.goal, 120) if (h.x, h.y) != h.goal else None
                if nxt is None or h.goal_ttl <= 0:
                    h.goal = None
                else:
                    h.x, h.y = nxt
                    continue
            self._wander(h)

    def _wander(self, h: Hornet) -> None:
        h.mode = "wander"
        opts = [d for d in DIRS4 if self.world.open_for_hornet(h.x + d[0], h.y + d[1])]
        if not opts:
            return
        ahead = [d for d in opts if d != (-h.heading[0], -h.heading[1])]
        if h.heading in opts and self.rng.random() < 0.8:
            d = h.heading
        else:
            d = (ahead or opts)[self.rng.randrange(len(ahead or opts))]
        h.heading = d
        h.x, h.y = h.x + d[0], h.y + d[1]

    def stings(self, bees: list[tuple[int, int, int, float]], t: int) -> list[tuple[Hornet, int]]:
        """Each hornet stings at most one adjacent bee outside the hive per tick, respecting the cooldown."""
        out = []
        for h in self.active:
            adj = [b for b in bees if abs(b[1] - h.x) + abs(b[2] - h.y) == 1 and self.cooldown.get((h.id, b[0]), -1) <= t]
            if not adj:
                continue
            b = next((b for b in adj if b[0] == h.target), max(adj, key=lambda b: (b[3], -b[0])))
            self.cooldown[(h.id, b[0])] = t + self.cooldown_ticks
            out.append((h, b[0]))
        return out

    def reward(self, h: Hornet, amount: float, where: tuple[int, int]) -> None:
        h.removed += amount
        h.spots = (h.spots + [where])[-3:]

"""Motor layer (no AI): turns a bee's intent into one step, using only that bee's own known map.

KnownMap holds what the bee has seen: unknown, open, wall or home. Route planning is A* over it, with
unknown cells counted as passable; a route is replanned as soon as a wall turns up on it. `explore`
heads for the nearest frontier (a known open cell beside an unknown one) within 50 degrees of the chosen
direction. `flee` steps to maximise distance from the hornets the bee can see. Nothing here reads the World.
"""
from __future__ import annotations

import heapq
import math
from collections import deque
from dataclasses import dataclass, field

from .perception import DIR_VEC, DIRECTIONS, Decision, direction_of

UNKNOWN, KOPEN, KWALL, KHIVE = 0, 1, 2, 3
DIRS4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
CONE_COS = math.cos(math.radians(50))


class KnownMap:
    def __init__(self, width: int, height: int, home: tuple[int, int]):
        self.w, self.h, self.home = width, height, home
        self.cells = bytearray(width * height)
        self.known = [0] * 8
        self.total = [0] * 8
        self.octant = bytearray(width * height)
        hx, hy = home
        for y in range(height):
            for x in range(width):
                o = DIRECTIONS.index(direction_of(x - hx, y - hy)) if (x, y) != home else 0
                self.octant[y * width + x] = o
                self.total[o] += 1

    def get(self, x: int, y: int) -> int:
        if 0 <= x < self.w and 0 <= y < self.h:
            return self.cells[y * self.w + x]
        return KWALL

    def learn(self, x: int, y: int, kind: int) -> bool:
        i = y * self.w + x
        if self.cells[i] == UNKNOWN:
            self.cells[i] = kind
            self.known[self.octant[i]] += 1
            return True
        return False

    def passable(self, x: int, y: int) -> bool:
        return 0 <= x < self.w and 0 <= y < self.h and self.cells[y * self.w + x] != KWALL

    def walkable_known(self, x: int, y: int) -> bool:
        return self.get(x, y) in (KOPEN, KHIVE)

    def frontier(self, x: int, y: int) -> bool:
        return self.walkable_known(x, y) and any(
            0 <= x + dx < self.w and 0 <= y + dy < self.h and self.cells[(y + dy) * self.w + x + dx] == UNKNOWN for dx, dy in DIRS4)

    def explored(self) -> dict[str, float]:
        return {d: round(self.known[i] / self.total[i], 3) if self.total[i] else 1.0 for i, d in enumerate(DIRECTIONS)}


@dataclass
class MotorState:
    key: str | None = None
    goal: tuple[int, int] | None = None
    path: list = field(default_factory=list)  # remaining route, next cell last


def astar(km: KnownMap, start, goal, max_nodes: int = 6000):
    """Shortest route on the known map, unknown cells passable. Returns cells goal-first (pop() = next)."""
    if start == goal:
        return []
    gx, gy = goal
    came, cost = {start: None}, {start: 0}
    heap = [(abs(start[0] - gx) + abs(start[1] - gy), 0, start)]
    expanded = 0
    while heap:
        _, neg_g, c = heapq.heappop(heap)
        if c == goal:
            path = []
            while c != start:
                path.append(c)
                c = came[c]
            return path
        g = -neg_g
        if g > cost[c]:
            continue
        expanded += 1
        if expanded > max_nodes:
            return None
        for dx, dy in DIRS4:
            n = (c[0] + dx, c[1] + dy)
            if km.passable(*n) and g + 1 < cost.get(n, 1 << 30):
                cost[n], came[n] = g + 1, c
                heapq.heappush(heap, (g + 1 + abs(n[0] - gx) + abs(n[1] - gy), -(g + 1), n))
    return None


def find_frontier(km: KnownMap, start, direction: str, max_nodes: int = 4000):
    """Nearest frontier cell (by route over known cells) inside the 50-degree cone of `direction`."""
    vx, vy = DIR_VEC[direction]
    vlen = math.hypot(vx, vy)
    came = {start: None}
    q = deque([start])
    while q and len(came) < max_nodes:
        c = q.popleft()
        if c != start:
            dx, dy = c[0] - start[0], c[1] - start[1]
            if dx * vx + dy * vy >= CONE_COS * math.hypot(dx, dy) * vlen and km.frontier(*c):
                path = []
                while c != start:
                    path.append(c)
                    c = came[c]
                return path[0], path
        for dx, dy in DIRS4:
            n = (c[0] + dx, c[1] + dy)
            if n not in came and km.walkable_known(*n):
                came[n] = c
                q.append(n)
    return None


def flee_step(km: KnownMap, pos, hornets):
    """The cell (staying put included) that maximises the nearest seen hornet's distance; ties go homeward."""
    opts = [pos] + [(pos[0] + dx, pos[1] + dy) for dx, dy in DIRS4 if km.walkable_known(pos[0] + dx, pos[1] + dy)]
    hx, hy = km.home
    return max(opts, key=lambda c: (min(abs(c[0] - a) + abs(c[1] - b) for a, b in hornets),
                                    -(abs(c[0] - hx) + abs(c[1] - hy)), c))


def step(km: KnownMap, pos, d: Decision, ms: MotorState, hornets_seen) -> tuple[tuple[int, int], str]:
    """One step for the intent. Returns (next cell, status): moving, arrived, blocked or idle."""
    if d.intent == "wait":
        return pos, "idle"
    if d.intent == "flee":
        if not hornets_seen:
            return pos, "arrived"
        return flee_step(km, pos, hornets_seen), "moving"
    label = d.label()
    if label != ms.key:
        ms.key, ms.goal, ms.path = label, None, []
    if d.intent == "go_home":
        if km.get(*pos) == KHIVE:
            return pos, "arrived"
        goal = km.home
    elif d.intent == "go_to":
        goal = tuple(d.target)
        if pos == goal:
            return pos, "arrived"
        if not km.passable(*goal):
            return pos, "blocked"
    else:  # explore
        if ms.goal is None or pos == ms.goal or not km.frontier(*ms.goal):
            found = find_frontier(km, pos, d.direction)
            if found is None:
                ms.goal, ms.path = None, []
                return pos, "arrived"
            ms.goal, ms.path = found
        goal = ms.goal
    if ms.goal != goal or not ms.path or any(km.get(*c) == KWALL for c in ms.path):
        ms.goal, ms.path = goal, astar(km, pos, goal) or []
        if not ms.path:
            return pos, "blocked"
    nxt = ms.path.pop()
    if abs(nxt[0] - pos[0]) + abs(nxt[1] - pos[1]) != 1:  # route no longer starts here (e.g. after a stun)
        ms.path = astar(km, pos, goal) or []
        if not ms.path:
            return pos, "blocked"
        nxt = ms.path.pop()
    return nxt, "moving"

"""Bee policies: what turns a Perception into a Decision.

The interface phase 2's AI mind implements:
    decide_many(perceptions) -> decisions   one call per tick with every bee that is due to decide
    bee_died(bee_id)                        optional clean-up
A policy never receives the World. The one exception is OraclePolicy, a calibration-only cheat that is
handed the current bloom cells at construction; it is never reported as a result.
"""
from __future__ import annotations

from .perception import DIRECTIONS, Decision, Perception


class Policy:
    name = "base"

    def decide(self, p: Perception) -> Decision:
        raise NotImplementedError

    def decide_many(self, perceptions: list[Perception]) -> list[Decision]:
        return [self.decide(p) for p in perceptions]

    def bee_died(self, bee_id: int) -> None:
        pass


class RandomPolicy(Policy):
    """Random intents and random sounds, with no use of what the bee perceives."""
    name = "random"

    def __init__(self, rng):
        self.rng = rng

    def decide(self, p: Perception) -> Decision:
        r = self.rng
        intent = ("explore", "go_to", "go_home", "flee", "wait")[r.randrange(5)]
        return Decision(intent=intent, direction=DIRECTIONS[r.randrange(8)],
                        target=(r.randrange(p.grid_size[0]), r.randrange(p.grid_size[1])),
                        sound=("none", "sound-1", "sound-2")[r.randrange(3)])


class RulePolicy(Policy):
    """Explore in a random direction, take bloom it sees, go home when carrying or at half the life it
    left home with. No sounds, no talk, no memory of bloom between trips."""
    name = "rule"

    def __init__(self, rng, return_fraction: float = 0.5):
        self.rng, self.return_fraction = rng, return_fraction
        self.heading: dict[int, str] = {}

    def decide(self, p: Perception) -> Decision:
        if p.carrying:
            return Decision("go_home")
        if not p.at_home and p.life_when_left_home and p.life <= self.return_fraction * p.life_when_left_home:
            return Decision("go_home")
        if p.bloom_seen:
            x, y = p.position
            return Decision("go_to", target=min(p.bloom_seen, key=lambda c: (abs(c[0] - x) + abs(c[1] - y), c)))
        h = self.heading.get(p.bee_id)
        if h is None or p.at_home or (p.trigger == "arrived" and p.motor_status in ("arrived", "blocked")):
            h = self.heading[p.bee_id] = DIRECTIONS[self.rng.randrange(8)]
        return Decision("explore", direction=h)

    def bee_died(self, bee_id: int) -> None:
        self.heading.pop(bee_id, None)


class OraclePolicy(Policy):
    """Calibration only: told where this season's bloom is. Goes there, carries home, waits out winter."""
    name = "oracle"

    def __init__(self, bloom_now):
        self.bloom_now = bloom_now

    def decide(self, p: Perception) -> Decision:
        if p.carrying:
            return Decision("go_home")
        cells = self.bloom_now()
        if not cells:
            return Decision("wait") if p.at_home else Decision("go_home")
        x, y = p.position
        return Decision("go_to", target=min(cells, key=lambda c: (abs(c[0] - x) + abs(c[1] - y), c)))


def make_policy(name: str, rng, *, bloom_now=None, params: dict | None = None) -> Policy:
    params = params or {}
    if name == "random":
        return RandomPolicy(rng)
    if name == "rule":
        return RulePolicy(rng, params.get("return_fraction", 0.5))
    if name == "oracle":
        return OraclePolicy(bloom_now)
    raise ValueError(f"unknown policy {name!r}")

"""Writes a run directory in the format documented in docs/BUILD_NOTES.md ("Log format")."""
from __future__ import annotations

import gzip
import json

FORMAT = 1
BEE_FIELDS = ["id", "x", "y", "life", "carrying", "stunned", "intent"]
HORNET_FIELDS = ["id", "x", "y", "smell", "hearing", "ambush", "target", "mode"]
SOUND_FIELDS = ["bee", "x", "y", "sound"]


class SimLog:
    """Wraps a RunLog. With log=None every call is a no-op, so tests can run the sim without files."""

    def __init__(self, log, *, state: bool = True, decisions: bool = True):
        self.log, self.decisions = log, decisions
        self._state = gzip.open(log.path("state.jsonl.gz"), "wt", compresslevel=6) if (log and state) else None

    def layout(self, world, cal, p: dict, seed: int, vision: tuple[int, int, int]) -> None:
        if not self.log:
            return
        doc = {
            "format": FORMAT, "width": world.width, "height": world.height, "rows": world.rows(),
            "home": list(world.home), "entrances": [list(e) for e in world.entrances],
            "bloom": {s: [list(c) for c in cs] for s, cs in world.bloom.items()},
            "bloom_distance": world.bloom_distance,
            "season_names": ["spring", "summer", "autumn", "winter"],
            "season_length": cal.season_length, "years": cal.years, "ticks": cal.ticks,
            "base_life": p["base_life"], "life_cap": p["base_life"] * p["life_cap_factor"], "max_bees": p["max_bees"],
            "vision": vision[0], "bloom_vision": vision[1], "hearing": vision[2],
            "condition": p["condition"], "seed": seed,
            "bee_fields": BEE_FIELDS, "hornet_fields": HORNET_FIELDS, "sound_fields": SOUND_FIELDS,
        }
        self.log.path("layout.json").write_text(json.dumps(doc, separators=(",", ":")) + "\n")

    def event(self, kind: str, t: int, **data) -> None:
        if self.log and (self.decisions or kind != "decision"):
            self.log.event(kind, t=t, **data)

    def metric(self, row: dict) -> None:
        if self.log:
            self.log.metric(**row)

    def state(self, t: int, season: int, year: int, bees, hornets, sounds) -> None:
        if not self._state:
            return
        line = {
            "t": t, "s": season, "y": year,
            "b": [[b.id, b.x, b.y, round(b.life, 1), int(b.carrying), b.stunned, b.labelled] for b in bees],
            "h": [[h.id, h.x, h.y, *h.genes, h.target, h.mode] for h in hornets],
            "snd": [list(s) for s in sounds],
        }
        self._state.write(json.dumps(line, separators=(",", ":")) + "\n")

    def close(self) -> None:
        if self._state:
            self._state.close()

